  SELECT 'rfn_financeiro__extrato_ancora_arquivo' AS t, 'ponte_nao_quebra' AS k, 'VALIDADE' AS d, 'saldo final de cada arquivo = saldo anterior do seguinte (base: zero quebras em 18 pontes em 19/10)' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNTIF(diferenca_ponte IS NOT NULL) AS n, COUNTIF(flag_ponte_quebrada) AS f FROM vanguardamartech_refined.rfn_financeiro__extrato_ancora_arquivo UNION ALL
  SELECT 'rfn_financeiro__custo_area_mensal' AS t, 'com_mais_sem_centro_fecha_o_total' AS k, 'VALIDADE' AS d, 'custo com centro + sem centro = custo total do mes (um centavo)' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF(ABS(custo_sem_centro_abs + custo_com_centro_abs - custo_total_abs) > 0.01) AS f FROM vanguardamartech_refined.rfn_financeiro__custo_area_mensal UNION ALL
  SELECT 'rfn_financeiro__pontualidade_resumo' AS t, 'atraso_nao_excede_pagos' AS k, 'VALIDADE' AS d, 'pagamentos em atraso nunca excedem os pagamentos' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNTIF(n_atraso_t0 IS NOT NULL) AS n, COUNTIF(n_atraso_t0 > n_pagos) AS f FROM vanguardamartech_refined.rfn_financeiro__pontualidade_resumo UNION ALL
  SELECT 'rfn_financeiro__titulo_receber_aging' AS t, 'faixa_so_em_aberto' AS k, 'VALIDADE' AS d, 'toda linha EM_ABERTO tem faixa de aging e nenhuma outra situacao tem' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF((situacao = 'EM_ABERTO' AND faixa_aging IS NULL) OR (situacao <> 'EM_ABERTO' AND faixa_aging IS NOT NULL)) AS f FROM vanguardamartech_refined.rfn_financeiro__titulo_receber_aging UNION ALL
  SELECT 'rfn_financeiro__lancamento_destino_resumo' AS t, 'nao_catalogado_sem_valor' AS k, 'VALIDADE' AS d, 'lancamento nao catalogado no movimento nao carrega valor (NULL, nunca zero)' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNTIF(flag_lancamento_nao_catalogado) AS n, COUNTIF(flag_lancamento_nao_catalogado AND valor_abs_movimento IS NOT NULL) AS f FROM vanguardamartech_refined.rfn_financeiro__lancamento_destino_resumo UNION ALL
  SELECT 'rfn_financeiro__migracao_ca_resumo' AS t, 'parcelas_so_na_duplicidade' AS k, 'VALIDADE' AS d, 'qtd_parcelas existe na duplicidade e e NULL na lacuna' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF((origem = 'DUPLICIDADE_CA' AND qtd_parcelas IS NULL) OR (origem = 'LACUNA_MIGRACAO' AND qtd_parcelas IS NOT NULL)) AS f FROM vanguardamartech_refined.rfn_financeiro__migracao_ca_resumo UNION ALL
  SELECT 'rfn_midia_off__pi_removido_resumo' AS t, 'existentes_nao_excedem_pis' AS k, 'VALIDADE' AS d, 'PIs que existem no PI atual nunca excedem os PIs da linha' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF(qtd_existe_no_pi_atual > qtd_pis) AS f FROM vanguardamartech_refined.rfn_midia_off__pi_removido_resumo UNION ALL
  SELECT 'trs_financeiro__contrato_inferido' AS t, 'pessoa_catalogada' AS k, 'INTEGRIDADE' AS d, 'contrato com pessoa encontra a pessoa no cadastro do Conta Azul (base: 179 de 179 em 19/10)' AS x, 'ALERTA' AS s, 0.98 AS lim, COUNTIF(c.id_pessoa IS NOT NULL) AS n, COUNTIF(c.id_pessoa IS NOT NULL AND p.id_pessoa IS NULL) AS f FROM vanguardamartech_trusted.trs_financeiro__contrato_inferido c LEFT JOIN (SELECT DISTINCT id_pessoa FROM vanguardamartech_trusted.trs_contazul__pessoa) p ON p.id_pessoa = c.id_pessoa UNION ALL
  SELECT 'trs_financeiro__dre_categoria_mes' AS t, 'sinal_do_resultado' AS k, 'VALIDADE' AS d, 'resultado = +bruto em RECEITA e -bruto em DESPESA (um centavo)' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNTIF(tipo_categoria IN ('RECEITA', 'DESPESA')) AS n, COUNTIF(tipo_categoria IN ('RECEITA', 'DESPESA') AND ABS(IF(tipo_categoria = 'RECEITA', resultado - valor_bruto, resultado + valor_bruto)) > 0.005) AS f FROM vanguardamartech_trusted.trs_financeiro__dre_categoria_mes UNION ALL
  SELECT 'trs_financeiro__mrr_projetado' AS t, 'arpa_reproduz_a_razao' AS k, 'VALIDADE' AS d, 'arpa = mrr / contratos ativos (um centavo)' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNTIF(contratos_ativos > 0) AS n, COUNTIF(contratos_ativos > 0 AND ABS(arpa - mrr / contratos_ativos) > 0.01) AS f FROM vanguardamartech_trusted.trs_financeiro__mrr_projetado UNION ALL
  SELECT 'trs_financeiro__extrato_ancora' AS t, 'arquivo_tem_duas_ancoras' AS k, 'VALIDADE' AS d, 'todo arquivo tem uma ancora anterior e uma final' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF(c <> 2) AS f FROM (SELECT COUNT(*) AS c FROM vanguardamartech_trusted.trs_financeiro__extrato_ancora GROUP BY conta_ref, arquivo) UNION ALL
  SELECT 'trs_financeiro__extrato_ancora' AS t, 'conta_com_depara' AS k, 'INTEGRIDADE' AS d, 'toda ancora encontra a conta no de-para' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF(flag_conta_sem_depara) AS f FROM vanguardamartech_trusted.trs_financeiro__extrato_ancora UNION ALL
  SELECT 'trs_financeiro__custo_area_mes' AS t, 'custo_nunca_positivo' AS k, 'VALIDADE' AS d, 'custo_total e sempre de saida (menor ou igual a zero)' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF(custo_total > 0) AS f FROM vanguardamartech_trusted.trs_financeiro__custo_area_mes UNION ALL
  SELECT 'trs_financeiro__pontualidade_cliente' AS t, 'documento_tem_forma' AS k, 'VALIDADE' AS d, 'documento so existe com 14 (CNPJ) ou 11 (CPF) digitos' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNTIF(documento IS NOT NULL) AS n, COUNTIF(documento IS NOT NULL AND LENGTH(documento) NOT IN (11, 14)) AS f FROM vanguardamartech_trusted.trs_financeiro__pontualidade_cliente UNION ALL
  SELECT 'trs_financeiro__pontualidade_cliente' AS t, 'ordem_dos_atrasos' AS k, 'VALIDADE' AS d, 'atraso t0 >= t3 >= t7' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNTIF(n_atraso_t0 IS NOT NULL) AS n, COUNTIF(n_atraso_t0 < n_atraso_t3 OR n_atraso_t3 < n_atraso_t7) AS f FROM vanguardamartech_trusted.trs_financeiro__pontualidade_cliente UNION ALL
  SELECT 'trs_financeiro__pontualidade_cliente' AS t, 'base_decompoe_os_pagos' AS k, 'VALIDADE' AS d, 'na BASE_CA n_pagos = pagos do iClips + pagos da era atual' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNTIF(origem = 'BASE_CA') AS n, COUNTIF(origem = 'BASE_CA' AND n_pagos <> pagos_iclips + pagos_era_atual) AS f FROM vanguardamartech_trusted.trs_financeiro__pontualidade_cliente UNION ALL
  SELECT 'trs_financeiro__pontualidade_cliente' AS t, 'iclips_dentro_da_base' AS k, 'INTEGRIDADE' AS d, 'todo cliente da ICLIPS_CRONICO esta na BASE_CA (superconjunto; 514 de 514 em 19/10)' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNTIF(i.origem = 'ICLIPS_CRONICO') AS n, COUNTIF(i.origem = 'ICLIPS_CRONICO' AND b.id_pontualidade IS NULL) AS f FROM vanguardamartech_trusted.trs_financeiro__pontualidade_cliente i LEFT JOIN vanguardamartech_trusted.trs_financeiro__pontualidade_cliente b ON b.origem = 'BASE_CA' AND b.operacao = i.operacao AND b.cliente_key = CONCAT('CA:', i.cliente_key) UNION ALL
  SELECT 'trs_financeiro__titulo_receber' AS t, 'saldo_nao_negativo' AS k, 'VALIDADE' AS d, 'saldo em aberto nunca e negativo' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF(saldo_aberto < 0) AS f FROM vanguardamartech_trusted.trs_financeiro__titulo_receber UNION ALL
  SELECT 'trs_financeiro__titulo_receber' AS t, 'prefixo_concorda_com_o_sistema' AS k, 'VALIDADE' AS d, 'prefixo do id (CA: ou VBOT:) concorda com o sistema de origem' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF((sistema_origem = 'Conta Azul') <> STARTS_WITH(id_titulo, 'CA:') OR (sistema_origem = 'Conexa') <> STARTS_WITH(id_titulo, 'VBOT:')) AS f FROM vanguardamartech_trusted.trs_financeiro__titulo_receber UNION ALL
  SELECT 'trs_financeiro__titulo_receber' AS t, 'documento_tem_forma' AS k, 'VALIDADE' AS d, 'documento so existe com 14 ou 11 digitos' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNTIF(documento IS NOT NULL) AS n, COUNTIF(documento IS NOT NULL AND LENGTH(documento) NOT IN (11, 14)) AS f FROM vanguardamartech_trusted.trs_financeiro__titulo_receber UNION ALL
  SELECT 'trs_financeiro__titulo_receber' AS t, 'conta_azul_existe_no_razao' AS k, 'INTEGRIDADE' AS d, 'titulo do Conta Azul encontra a parcela vigente de entrada no razao (base: 2.522 de 2.522; o razao anda semanal)' AS x, 'ALERTA' AS s, 0.98 AS lim, COUNTIF(t.sistema_origem = 'Conta Azul') AS n, COUNTIF(t.sistema_origem = 'Conta Azul' AND m.id_movimento IS NULL) AS f FROM vanguardamartech_trusted.trs_financeiro__titulo_receber t LEFT JOIN (SELECT DISTINCT id_movimento FROM vanguardamartech_trusted.trs_contazul__movimento WHERE is_vigente AND sentido = 'ENTRADA') m ON m.id_movimento = SUBSTR(t.id_titulo, 4) UNION ALL
  SELECT 'trs_financeiro__titulo_receber' AS t, 'conexa_existe_na_cobranca' AS k, 'INTEGRIDADE' AS d, 'titulo do Conexa encontra a cobranca na Trusted (base: 968 de 968)' AS x, 'ALERTA' AS s, 0.99 AS lim, COUNTIF(t.sistema_origem = 'Conexa') AS n, COUNTIF(t.sistema_origem = 'Conexa' AND c.id IS NULL) AS f FROM vanguardamartech_trusted.trs_financeiro__titulo_receber t LEFT JOIN (SELECT DISTINCT CAST(id_cobranca AS STRING) AS id FROM vanguardamartech_trusted.trs_conexa__cobranca) c ON c.id = SUBSTR(t.id_titulo, 6) UNION ALL
  SELECT 'trs_financeiro__lancamento_destino' AS t, 'sentido_concorda_com_o_movimento' AS k, 'VALIDADE' AS d, 'o tipo do destino concorda com o sentido do movimento casado' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNT(*) AS n, COUNTIF(d.sentido <> m.sentido) AS f FROM vanguardamartech_trusted.trs_financeiro__lancamento_destino d INNER JOIN vanguardamartech_trusted.trs_financeiro__movimento m ON m.id_movimento = d.id_lancamento UNION ALL
  SELECT 'trs_financeiro__lancamento_destino' AS t, 'lancamento_catalogado' AS k, 'INTEGRIDADE' AS d, 'lancamento do destino encontra o movimento (base: 44.034 de 44.142 = 99,76%; os 108 sem par sao A Receber)' AS x, 'ALERTA' AS s, 0.99 AS lim, COUNT(*) AS n, COUNTIF(flag_lancamento_nao_catalogado) AS f FROM vanguardamartech_trusted.trs_financeiro__lancamento_destino UNION ALL
  SELECT 'trs_financeiro__lancamento_destino' AS t, 'documento_sem_fragmento' AS k, 'VALIDADE' AS d, 'nenhum documento do destino fora da forma de 14 ou 11 digitos' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNTIF(documento_origem IS NOT NULL) AS n, COUNTIF(flag_documento_invalido) AS f FROM vanguardamartech_trusted.trs_financeiro__lancamento_destino UNION ALL
  SELECT 'trs_financeiro__migracao_ca' AS t, 'ids_batem_com_as_parcelas' AS k, 'VALIDADE' AS d, 'na duplicidade o numero de ids de parcela = qtd_parcelas' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNTIF(origem = 'DUPLICIDADE_CA') AS n, COUNTIF(origem = 'DUPLICIDADE_CA' AND ARRAY_LENGTH(ids_parcelas) <> qtd_parcelas) AS f FROM vanguardamartech_trusted.trs_financeiro__migracao_ca UNION ALL
  SELECT 'trs_financeiro__migracao_ca' AS t, 'situacao_conhecida' AS k, 'VALIDADE' AS d, 'a situacao da lacuna e uma das cinco conhecidas (valor novo acende o gatilho de manutencao)' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNTIF(origem = 'LACUNA_MIGRACAO') AS n, COUNTIF(origem = 'LACUNA_MIGRACAO' AND (situacao IS NULL OR situacao NOT IN ('OK_MIGRADO', 'NAO_MIGRADO_CLIENTE_EXISTE', 'NAO_MIGRADO_CLIENTE_AUSENTE', 'OK_MIGRADO_VENC_AJUSTADO', 'PROVAVEL_CADASTRO_DIVERGENTE'))) AS f FROM vanguardamartech_trusted.trs_financeiro__migracao_ca UNION ALL
  SELECT 'trs_financeiro__migracao_ca' AS t, 'lacuna_existe_no_movimento' AS k, 'INTEGRIDADE' AS d, 'lancamento da lacuna encontra o movimento do iClips (base: 292 de 292)' AS x, 'ALERTA' AS s, 0.98 AS lim, COUNTIF(g.origem = 'LACUNA_MIGRACAO') AS n, COUNTIF(g.origem = 'LACUNA_MIGRACAO' AND m.id_movimento IS NULL) AS f FROM vanguardamartech_trusted.trs_financeiro__migracao_ca g LEFT JOIN (SELECT DISTINCT id_movimento FROM vanguardamartech_trusted.trs_financeiro__movimento) m ON m.id_movimento = g.codigo_lancamento_iclips UNION ALL
  SELECT 'trs_financeiro__migracao_ca' AS t, 'duplicidade_existe_no_razao' AS k, 'INTEGRIDADE' AS d, 'parcela da duplicidade encontra o razao do Conta Azul (base: 748 de 748; o razao anda semanal)' AS x, 'ALERTA' AS s, 0.98 AS lim, COUNT(*) AS n, COUNTIF(m.id_movimento IS NULL) AS f FROM (SELECT id FROM vanguardamartech_trusted.trs_financeiro__migracao_ca, UNNEST(ids_parcelas) AS id WHERE origem = 'DUPLICIDADE_CA') d LEFT JOIN (SELECT DISTINCT id_movimento FROM vanguardamartech_trusted.trs_contazul__movimento) m ON m.id_movimento = d.id UNION ALL
  SELECT 'trs_financeiro__parametro_auditoria' AS t, 'antes_e_depois_coerentes' AS k, 'VALIDADE' AS d, 'insert nao traz valores_antes e update traz' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNTIF(origem = 'PARAM_DEPARA_AUDIT') AS n, COUNTIF(flag_insert_com_antes OR flag_update_sem_antes) AS f FROM vanguardamartech_trusted.trs_financeiro__parametro_auditoria UNION ALL
  SELECT 'trs_financeiro__parametro_auditoria' AS t, 'no_id_extraido_do_json' AS k, 'VALIDADE' AS d, 'toda edicao do de-para traz o id do no no JSON de depois' AS x, 'ALERTA' AS s, 1.0 AS lim, COUNTIF(origem = 'PARAM_DEPARA_AUDIT') AS n, COUNTIF(origem = 'PARAM_DEPARA_AUDIT' AND no_id_depois IS NULL) AS f FROM vanguardamartech_trusted.trs_financeiro__parametro_auditoria UNION ALL
  SELECT 'trs_pi__removido' AS t, 'reapareceu_existe_no_pi_atual' AS k, 'INTEGRIDADE' AS d, 'PI que reapareceu existe no PI atual (base: 73 de 73)' AS x, 'ALERTA' AS s, 0.95 AS lim, COUNTIF(flag_reapareceu) AS n, COUNTIF(flag_reapareceu AND NOT flag_existe_no_pi_atual) AS f FROM vanguardamartech_trusted.trs_pi__removido UNION ALL
  SELECT 'trs_pi__removido' AS t, 'cnpj_veiculo_tem_forma' AS k, 'VALIDADE' AS d, 'cnpj do veiculo so existe com 14 digitos (13 so repadronizado quando o corrigido existe)' AS x, 'BLOQUEANTE' AS s, 1.0 AS lim, COUNTIF(cnpj_veiculo_origem IS NOT NULL) AS n, COUNTIF(flag_cnpj_veiculo_invalido) AS f FROM vanguardamartech_trusted.trs_pi__removido UNION ALL
  SELECT 'trs_pi__removido' AS t, 'liquido_mais_comissao_e_o_negociado' AS k, 'VALIDADE' AS d, 'valor liquido + comissao do veiculo = valor negociado (um centavo)' AS x, 'ALERTA' AS s, 0.99 AS lim, COUNT(*) AS n, COUNTIF(ABS(valor_negociado - valor_liquido - valor_comissao_veiculo) > 0.01) AS f FROM vanguardamartech_trusted.trs_pi__removido
),
todas AS (
  SELECT CONCAT(t, '.chave_unica') AS id_regra, t AS tabela, 'UNICIDADE' AS dimensao, CONCAT('a chave da tabela e unica e nunca nula') AS regra, 'BLOQUEANTE' AS severidade, 1.00 AS limiar, n AS linhas_avaliadas, f AS linhas_falha FROM u
  UNION ALL
  SELECT CONCAT(t, '.', k), t, 'VALIDADE', x, 'BLOQUEANTE', 1.00, 1, IF(ABS(IFNULL(a, 0) - IFNULL(b, 0)) <= tol, 0, 1) FROM i
  UNION ALL
  SELECT CONCAT(t, '.', k), t, d, x, s, lim, n, f FROM v
  UNION ALL
  SELECT 'financeiro_residuo.carga_do_mesmo_dia', 'rfn_financeiro_residuo (11 Refined)', 'FRESCOR', 'as 11 Refined foram escritas na mesma passada (mesma data de carga)', 'ALERTA', 1.00, COUNT(*), COUNTIF(d <> (SELECT MAX(d) FROM c)) FROM c
),
avaliado AS (
  SELECT
    t.id_regra,
    IF(STARTS_WITH(t.tabela, 'trs_'), 'Trusted', 'Refined') AS camada,
    t.tabela,
    IF(t.tabela IN ('trs_pi__removido', 'rfn_midia_off__pi_removido_resumo'), 'PI', 'Financeiro') AS sistema,
    t.dimensao, t.regra, t.severidade, t.limiar, t.linhas_avaliadas, t.linhas_falha,
    (t.linhas_avaliadas - t.linhas_falha)                       AS linhas_conformes,
    SAFE_DIVIDE(t.linhas_avaliadas - t.linhas_falha, NULLIF(t.linhas_avaliadas, 0)) AS taxa_conformidade,
    IF(t.linhas_avaliadas = 0, NULL, SAFE_DIVIDE(t.linhas_avaliadas - t.linhas_falha, t.linhas_avaliadas) >= t.limiar) AS is_conforme,
    (t.linhas_avaliadas = 0)                                    AS flag_sem_linha_para_avaliar
  FROM todas t
),
final AS (
  SELECT
    a.*,
    CASE
      WHEN a.flag_sem_linha_para_avaliar          THEN 'SEM_DADO'
      WHEN a.is_conforme                          THEN 'CONFORME'
      WHEN a.severidade = 'BLOQUEANTE'            THEN 'FALHA_BLOQUEANTE'
      ELSE                                             'FALHA_ALERTA'
    END                                           AS resultado,
    'FINANCEIRO_RESIDUO'                          AS familia,
    CURRENT_TIMESTAMP()                           AS _extraido_at,
    'supabase-x0tz'                               AS _fonte,
    'America/Sao_Paulo'                           AS _fuso,
    TO_HEX(MD5(TO_JSON_STRING(a)))                AS _payload_hash
  FROM avaliado a
)
SELECT * FROM final
